-- =====================================================================
-- OrderCraft - Oracle schema (Stage 2A)
-- Source of truth: OrderCraft Product and System Design Document (DRD), sections 4-5.
--
-- Target: Oracle Database 12c Release 1 (12.1) or newer.
--   ASSUMPTION: identity columns (GENERATED BY DEFAULT AS IDENTITY) require 12c+.
--   Constraint and index names are kept to 30 characters or fewer so the script
--   is also valid on 12.1 / 12.2 identifier limits.
--
-- Usage: run once, as the application schema owner, on an EMPTY schema
--   (SQL*Plus, SQLcl or SQL Developer "Run Script"). It is not executed by Spring Boot
--   and is not re-runnable (no DROP statements).
--
-- Creation order (parents before children):
--   ROLES -> USERS -> CUSTOMERS -> CUSTOMER_ORDERS -> ORDER_ITEMS -> BILLS -> PAYMENTS
--   SUPPLIERS is independent (no foreign keys, per DRD).
--
-- Derived values are NOT stored as balances: paid amount and amount due are
-- computed from PAYMENTS (DRD section 5). CUSTOMER_ORDERS.total_amount is a DRD column
-- that the service layer must keep equal to SUM(ORDER_ITEMS.line_total).
-- =====================================================================

-- ---------------------------------------------------------------------
-- ROLES
-- ---------------------------------------------------------------------
CREATE TABLE roles (
    role_id      NUMBER(19)         GENERATED BY DEFAULT AS IDENTITY,
    role_name    VARCHAR2(50 CHAR)  NOT NULL,
    description  VARCHAR2(255 CHAR),
    CONSTRAINT pk_roles PRIMARY KEY (role_id)
);

-- ---------------------------------------------------------------------
-- USERS  (role_id -> ROLES.role_id)
-- ---------------------------------------------------------------------
CREATE TABLE users (
    user_id        NUMBER(19)          GENERATED BY DEFAULT AS IDENTITY,
    role_id        NUMBER(19)          NOT NULL,
    full_name      VARCHAR2(150 CHAR)  NOT NULL,
    email          VARCHAR2(254 CHAR)  NOT NULL,
    password_hash  VARCHAR2(255 CHAR)  NOT NULL,
    status         VARCHAR2(20 CHAR)   NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (user_id),
    CONSTRAINT fk_users_role FOREIGN KEY (role_id) REFERENCES roles (role_id)
);

-- ---------------------------------------------------------------------
-- CUSTOMERS
-- ---------------------------------------------------------------------
CREATE TABLE customers (
    customer_id      NUMBER(19)          GENERATED BY DEFAULT AS IDENTITY,
    customer_name    VARCHAR2(150 CHAR)  NOT NULL,
    email            VARCHAR2(254 CHAR),
    phone            VARCHAR2(30 CHAR),
    billing_address  VARCHAR2(500 CHAR),
    status           VARCHAR2(20 CHAR)   NOT NULL,
    CONSTRAINT pk_customers PRIMARY KEY (customer_id)
);

-- ---------------------------------------------------------------------
-- CUSTOMER_ORDERS  (customer_id -> CUSTOMERS, created_by -> USERS)
-- Order statuses: NEW, CONFIRMED, PROCESSING, COMPLETED
-- ---------------------------------------------------------------------
CREATE TABLE customer_orders (
    order_id       NUMBER(19)         GENERATED BY DEFAULT AS IDENTITY,
    customer_id    NUMBER(19)         NOT NULL,
    created_by     NUMBER(19)         NOT NULL,
    order_date     DATE               NOT NULL,
    required_date  DATE               NOT NULL,
    status         VARCHAR2(20 CHAR)  NOT NULL,
    total_amount   NUMBER(15,2)       NOT NULL,
    CONSTRAINT pk_customer_orders PRIMARY KEY (order_id),
    CONSTRAINT fk_cust_orders_customer FOREIGN KEY (customer_id) REFERENCES customers (customer_id),
    CONSTRAINT fk_cust_orders_created_by FOREIGN KEY (created_by) REFERENCES users (user_id),
    CONSTRAINT ck_customer_orders_status CHECK (status IN ('NEW', 'CONFIRMED', 'PROCESSING', 'COMPLETED'))
);

-- ---------------------------------------------------------------------
-- ORDER_ITEMS  (order_id -> CUSTOMER_ORDERS)
-- line_total = quantity * unit_price (calculated by the service layer)
-- ---------------------------------------------------------------------
CREATE TABLE order_items (
    order_item_id  NUMBER(19)          GENERATED BY DEFAULT AS IDENTITY,
    order_id       NUMBER(19)          NOT NULL,
    item_code      VARCHAR2(50 CHAR)   NOT NULL,
    description    VARCHAR2(255 CHAR)  NOT NULL,
    quantity       NUMBER(12,3)        NOT NULL,
    unit_price     NUMBER(15,2)        NOT NULL,
    line_total     NUMBER(15,2)        NOT NULL,
    CONSTRAINT pk_order_items PRIMARY KEY (order_item_id),
    CONSTRAINT fk_order_items_order FOREIGN KEY (order_id) REFERENCES customer_orders (order_id),
    CONSTRAINT ck_order_items_quantity CHECK (quantity > 0),
    CONSTRAINT ck_order_items_unit_price CHECK (unit_price >= 0)
);

-- ---------------------------------------------------------------------
-- BILLS  (order_id -> CUSTOMER_ORDERS, UNIQUE: at most one bill per order)
-- Bill statuses: GENERATED, ISSUED
-- ---------------------------------------------------------------------
CREATE TABLE bills (
    bill_id       NUMBER(19)         GENERATED BY DEFAULT AS IDENTITY,
    order_id      NUMBER(19)         NOT NULL,
    bill_number   VARCHAR2(30 CHAR)  NOT NULL,
    bill_date     DATE               NOT NULL,
    subtotal      NUMBER(15,2)       NOT NULL,
    tax_amount    NUMBER(15,2)       NOT NULL,
    total_amount  NUMBER(15,2)       NOT NULL,
    status        VARCHAR2(20 CHAR)  NOT NULL,
    CONSTRAINT pk_bills PRIMARY KEY (bill_id),
    CONSTRAINT fk_bills_order FOREIGN KEY (order_id) REFERENCES customer_orders (order_id),
    CONSTRAINT uq_bills_order_id UNIQUE (order_id),
    CONSTRAINT uq_bills_bill_number UNIQUE (bill_number),
    CONSTRAINT ck_bills_status CHECK (status IN ('GENERATED', 'ISSUED'))
);

-- ---------------------------------------------------------------------
-- PAYMENTS  (bill_id -> BILLS)
-- status: allowed values are not finalized in the DRD, so NO check constraint is applied.
-- ---------------------------------------------------------------------
CREATE TABLE payments (
    payment_id    NUMBER(19)         GENERATED BY DEFAULT AS IDENTITY,
    bill_id       NUMBER(19)         NOT NULL,
    payment_date  DATE               NOT NULL,
    amount        NUMBER(15,2)       NOT NULL,
    method        VARCHAR2(50 CHAR)  NOT NULL,
    reference_no  VARCHAR2(100 CHAR),
    status        VARCHAR2(30 CHAR)  NOT NULL,
    CONSTRAINT pk_payments PRIMARY KEY (payment_id),
    CONSTRAINT fk_payments_bill FOREIGN KEY (bill_id) REFERENCES bills (bill_id),
    CONSTRAINT ck_payments_amount CHECK (amount > 0)
);

-- ---------------------------------------------------------------------
-- SUPPLIERS  (independent: no foreign keys, no order or purchase-order link)
-- Supplier statuses: ACTIVE, INACTIVE
-- ---------------------------------------------------------------------
CREATE TABLE suppliers (
    supplier_id     NUMBER(19)          GENERATED BY DEFAULT AS IDENTITY,
    supplier_name   VARCHAR2(150 CHAR)  NOT NULL,
    contact_person  VARCHAR2(100 CHAR)  NOT NULL,
    email           VARCHAR2(254 CHAR)  NOT NULL,
    phone           VARCHAR2(30 CHAR)   NOT NULL,
    address         VARCHAR2(500 CHAR),
    status          VARCHAR2(20 CHAR)   NOT NULL,
    CONSTRAINT pk_suppliers PRIMARY KEY (supplier_id),
    CONSTRAINT ck_suppliers_status CHECK (status IN ('ACTIVE', 'INACTIVE'))
);

-- ---------------------------------------------------------------------
-- Indexes (DRD: indexes on foreign keys and common search fields).
-- BILLS.order_id and BILLS.bill_number are already indexed by their UNIQUE constraints.
-- ---------------------------------------------------------------------
CREATE INDEX ix_users_role ON users (role_id);
CREATE INDEX ix_cust_orders_customer ON customer_orders (customer_id);
CREATE INDEX ix_cust_orders_created_by ON customer_orders (created_by);
CREATE INDEX ix_order_items_order ON order_items (order_id);
CREATE INDEX ix_payments_bill ON payments (bill_id);
CREATE INDEX ix_customers_name ON customers (customer_name);
CREATE INDEX ix_suppliers_name ON suppliers (supplier_name);